'use strict';
/* Dashboards (M-DSH), My work (OPS-04) and the approvals inbox (PLT-01) */

const Stat = {
  months(n) { const out = []; for (let i = n - 1; i >= 0; i--) out.push(monthKey(addMonths(today(), -i))); return out; },
  sales(m) { return DB.q('sales').filter(s => !['revoked', 'expired'].includes(s.status) && monthKey(s.date) === m); },
  collected(m) { return sum(DB.q('payments').filter(p => p.status === 'confirmed' && monthKey(p.date) === m), p => p.amount); },
  due(m) { return sum(DB.q('sales').filter(s => !['revoked', 'expired'].includes(s.status)), s => sum(s.schedule.filter(r => monthKey(r.due) === m), r => r.amount)); },
  receivables() { return sum(DB.q('sales').filter(s => ['active', 'pending'].includes(s.status)), s => saleBalance(s)); },
  aging() { const b = [0, 0, 0, 0]; overdueItems().forEach(o => { b[o.days <= 30 ? 0 : o.days <= 60 ? 1 : o.days <= 90 ? 2 : 3] += o.out; }); return b; },
  plots() { const c = {}; PLOT_STATUSES.forEach(s => c[s] = 0); DB.q('plots').forEach(p => c[p.status]++); return c; },
  pendingPay() { return DB.q('payments').filter(p => ['pending', 'awaiting second'].includes(p.status)); },
  attendanceToday() { const t = today(); const a = DB.q('attendance').filter(x => x.date === t); return { in: a.length, total: DB.q('employees').filter(e => e.status === 'Active' && e.userId !== 'u_aud').length, late: a.filter(x => x.late).length }; },
  medianReceiptMin() { const a = DB.q('payments').filter(p => p.status === 'confirmed' && p.confirmedAt && p.ts).map(p => (p.confirmedAt - p.ts) / 60000).sort((x, y) => x - y); return a.length ? Math.round(a[Math.floor(a.length / 2)]) : 0; }
};

const isCOO = u => /Chief Operating/.test(u.title);
const DASH_TABS = () => {
  const u = me(), r = u.role, t = []; const head = deptHead(u.dept) === u.id;
  if (r === 'superadmin') t.push({ k: 'sys', l: 'Super Admin' });
  if (r === 'groupexec') t.push(isCOO(u) ? { k: 'coo', l: 'Group Executive · COO' } : { k: 'md', l: 'Group Executive · MD' });
  if (isExec()) t.push({ k: 'company', l: 'Company Executive' });
  if (r === 'auditor') t.push({ k: 'audit', l: 'Auditor view' });
  if (r === 'finance') t.push({ k: 'officer', l: 'Finance Officer' });
  if (r === 'hr') t.push({ k: 'officer', l: 'HR Officer' });
  if (r === 'hod' || (head && r !== 'superadmin') || isExec()) t.push({ k: 'dept', l: 'Department (HOD)' });
  t.push({ k: 'me', l: r === 'staff' ? 'My dashboard' : 'Personal' });
  if (isExec() || r === 'superadmin') t.push({ k: 'schedules', l: 'Scheduled reports' });
  return t;
};

PAGES.dashboard = (parts) => {
  const tabsL = DASH_TABS(); const cur = parts[0] && tabsL.find(t => t.k === parts[0]) ? parts[0] : tabsL[0].k; const u = me();
  const hr_ = new Date().getHours(); const greet = `Good ${hr_ < 12 ? 'morning' : hr_ < 17 ? 'afternoon' : 'evening'}, ${esc(u.name.split(' ')[0])}`;
  const titles = { sys: `System${pi('settings', true)}overview`, md: `Group${pi('sparkle', true)}at a glance`, coo: `Running${pi('bolt', true)}the operation`, company: `Your business${pi('sparkle', true)}at a glance`, audit: `Audit${pi('shield', true)}view`, officer: u.role === 'finance' ? `Finance${pi('coins', true)}desk` : `HR${pi('briefcase', true)}desk`, dept: `Managing${pi('users', true)}your team and work`, schedules: `Scheduled${pi('mail', true)}reports`, me: greet };
  const acts = `<a class="iconbtn" href="#/profile" aria-label="Settings">${icon('settings')}</a>${approvalCount() ? `<a class="btn primary" href="#/approvals">${icon('shield', 'sm')} ${approvalCount()} waiting for you</a>` : (can('fin.confirm') ? `<a class="btn primary" href="#/finance/confirm">${icon('check', 'sm')} Confirm payments</a>` : `<a class="btn primary" href="#/mywork">${icon('check', 'sm')} Open my work</a>`)}`;
  const bodies = { sys: dashSystem, md: dashMD, coo: dashCOO, company: dashExec, audit: dashAuditor, officer: u.role === 'finance' ? dashFinOfficer : dashHrOfficer, dept: dashDept, schedules: dashSchedules, me: dashMe };
  return pageHead({ title: titles[cur], sub: esc(company().name) + ' · ' + fiscalYear().label + ' · ' + fmtDate(today()), acts }) + (tabsL.length > 1 ? tabs('dashboard', tabsL, cur) : '') + bodies[cur]();
};

/* Group Executive: MD */
function perCompany(fn) { const keep = CO; const out = []; try { DB.d.companies.filter(c => me().co.includes(c.id)).forEach(c => { CO = c.id; out.push({ c, ...fn(c) }); }); } finally { CO = keep; } return out; }
function dashMD() {
  const m = monthKey(today()); const cos = perCompany(() => ({ sales: sum(Stat.sales(m), s => s.total), nsales: Stat.sales(m).length, col: Stat.collected(m), rec: Stat.receivables(), od: sum(overdueItems(), o => o.out), cash: acctBal('1010'), tk: DB.q('tickets').filter(t => !['Resolved', 'Closed'].includes(t.status)).length, hc: DB.q('employees').filter(e => e.status === 'Active').length, pa: DB.q('approvals').filter(a => a.status === 'pending').length }));
  const big = DB.d.approvals.filter(a => a.status === 'pending' && a.amount >= 1000000 && !a.del && me().co.includes(a.co)).sort(by(a => a.amount, -1)).slice(0, 5);
  return `<div class="grid g4">${tile({ ic: 'wallet', title: 'Group cash and bank', value: moneyShort(sum(cos, c => c.cash)), sub: cos.length + ' companies', cls: 'dark' })}${tile({ cls: 'tea', ic: 'target', title: 'Sales this month', value: moneyShort(sum(cos, c => c.sales)), sub: sum(cos, c => c.nsales) + ' sales' })}${tile({ ic: 'coins', title: 'Collected this month', value: moneyShort(sum(cos, c => c.col)) })}${tile({ ic: 'scale', title: 'Overdue receivables', value: moneyShort(sum(cos, c => c.od)), sub: moneyShort(sum(cos, c => c.rec)) + ' outstanding' })}</div>
  <div class="grid g21" style="margin-top:16px;align-items:start">${card('Companies side by side', `<table class="tbl"><thead><tr><th>Company</th><th class="num">Sales</th><th class="num">Collected</th><th class="num">Receivable</th><th class="num">Cash</th><th class="num">Headcount</th><th class="num">Open tickets</th></tr></thead><tbody>${cos.map(c => `<tr><td><b style="font-weight:500">${esc(c.c.name)}</b></td><td class="num">${moneyShort(c.sales)}</td><td class="num">${moneyShort(c.col)}</td><td class="num">${moneyShort(c.rec)}</td><td class="num">${moneyShort(c.cash)}</td><td class="num">${c.hc}</td><td class="num">${c.tk}</td></tr>`).join('')}</tbody></table>`, { ic: 'building', acts: '<a class="btn sm" href="#/accounting/statements/pnl">Group statements</a>' })}${card('High-value items waiting', big.length ? big.map(a => `<a class="tilebtn" style="margin-bottom:8px" href="#/approvals">${icon('shield')}<span class="grow">${esc(a.title)}<br><span class="small muted">${esc(APPROVAL_LABEL[a.type] || a.type)} · ${esc(userName(a.requester))}</span></span><b style="font-weight:500">${moneyShort(a.amount)}</b></a>`).join('') : '<p class="muted">No high-value approvals waiting.</p>', { ic: 'shield', acts: '<a class="btn sm" href="#/approvals">All approvals</a>' })}</div>
  <div class="grid g2" style="margin-top:16px">${card('Sales by company this month', hbars(cos.map(c => ({ l: c.c.short, v: c.sales })), moneyShort), { ic: 'trend' })}${card('Executive KPIs', `<div class="stack" style="gap:12px">${[['Collections vs due this month', Stat.collected(m), Math.max(Stat.due(m), 1)], ['Plots sold', DB.q('plots').filter(p => ['allocated', 'paid', 'documented'].includes(p.status)).length, DB.q('plots').length || 1], ['Reports submitted on time', DB.q('reports').filter(r => r.submittedAt && isoDate(r.submittedAt) <= r.deadline).length, Math.max(DB.q('reports').filter(r => r.submittedAt).length, 1)]].map(([l, a, b]) => `<div><div class="row small"><span>${l}</span><span class="sp"></span><b style="font-weight:500">${pct(a, b)}%</b></div>${progress(a, b)}</div>`).join('')}</div>`, { ic: 'target' })}</div>`;
}
/* Group Executive: COO */
function dashCOO() {
  const m = monthKey(today()); const pend = DB.q('approvals').filter(a => a.status === 'pending'); const od = overdueItems(); const lvl = d => od.filter(o => (o.days > 90 ? 3 : o.days > 60 ? 2 : o.days > 30 ? 1 : 0) === d).length;
  const tk = DB.q('tickets'); const res = tk.filter(t => t.resolvedAt); const sla = res.length ? pct(res.filter(t => t.resolvedAt <= t.slaDue).length, res.length) : 100;
  const expiring = DB.q('plots').filter(p => p.status === 'reserved' && p.reservedUntil && p.reservedUntil <= addDays(today(), 2)); const docs = DB.q('plots').filter(p => p.status === 'paid').length;
  const overT = DB.q('tasks').filter(t => t.status !== 'done' && t.due && t.due < today());
  return `<div class="grid g4">${tile({ ic: 'shield', title: 'Approvals waiting', value: pend.length, cls: 'dark', sub: pend.filter(canDecide).length + ' for you', href: '#/approvals' })}${tile({ cls: 'tea', ic: 'coins', title: 'Payments to confirm', value: Stat.pendingPay().length, sub: moneyShort(sum(Stat.pendingPay(), p => p.amount)), href: '#/finance/confirm' })}${tile({ ic: 'headset', title: 'Tickets within SLA', value: sla + '%', pc: sla, sub: tk.filter(t => t.breached && !t.resolvedAt).length + ' breached now', href: '#/cx/sla' })}${tile({ ic: 'clipboard', title: 'Overdue tasks', value: overT.length, sub: uniq(overT.map(t => userById(t.assignee)?.dept)).length + ' departments', href: '#/work/reports' })}</div>
  <div class="grid g3" style="margin-top:16px">${card('Approvals by type', hbars(Object.entries(pend.reduce((o, a) => { o[a.type] = (o[a.type] || 0) + 1; return o; }, {})).map(([k, v]) => ({ l: APPROVAL_LABEL[k] || k, v })).concat(pend.length ? [] : [{ l: 'None waiting', v: 0 }])), { ic: 'shield' })}${card('Collections escalation', hbars([['Reminder', 0], ['HOD alert', 1], ['Executive', 2], ['Default review', 3]].map(([l, d]) => ({ l, v: lvl(d), warn: d > 1 }))), { ic: 'scale', acts: '<a class="btn sm" href="#/finance/collections">Open</a>' })}${card('Overdue tasks by department', hbars(DB.q('depts').map(d => ({ l: d.name, v: overT.filter(t => userById(t.assignee)?.dept === d.name).length, warn: true })).filter(x => x.v)), { ic: 'clipboard' })}</div>
  <div class="grid g2" style="margin-top:16px">${card('Operations watch', `${kv([['Reservations expiring in 2 days', expiring.length], ['Paid plots awaiting documents', docs], ['Realtors stalled', DB.q('realtors').filter(r => !['Inducted (Associate)', 'Maverick', 'Inactive', 'Exited'].includes(r.stage) && Date.now() - (r.lastActivity || 0) > DB.setting('realtorStallDays') * 864e5).length], ['Site inspections this week', DB.q('inspections').filter(i => i.date >= today() && i.date <= addDays(today(), 7) && i.status === 'Scheduled').length], ['Open facility requests', DB.q('facilityreqs').filter(f => f.status !== 'Completed').length], ['Period close', DB.q('periods').filter(p => p.status === 'open').length + ' months open']])}`, { ic: 'eye' })}${card('Department reports', `<table class="tbl"><thead><tr><th>Department</th><th>Latest</th><th>Status</th></tr></thead><tbody>${['Sales', 'Operations', 'Marketing', 'Customer Experience', 'Finance', 'HR'].map(d => { const r = DB.q('reports').filter(x => x.dept === d).sort(by(x => x.period, -1))[0]; return `<tr><td>${d}</td><td>${r ? fmtDate(r.period) : '—'}</td><td>${r ? spill(r.status) : spill('None', 'mute')}</td></tr>`; }).join('')}</tbody></table>`, { ic: 'file', acts: '<a class="btn sm" href="#/reports/digest">Weekly digest</a>' })}</div>`;
}
/* Auditor view */
function dashAuditor() {
  const au = DB.q('audit'); const checks = integrityChecks(); const bad = checks.filter(c => c.items.length).length; const week = au.filter(a => a.ts > Date.now() - 7 * 864e5);
  return `<div class="alert info" style="margin-bottom:14px">${icon('eye', 'sm')}<span>Read-only. Your access covers the scope granted to you${me().expires ? ' until <b>' + fmtDate(me().expires) + '</b>' : ''}. Salary, ID and disciplinary records are not visible to auditors.</span></div><div class="grid g4">${tile({ cls: 'dark', ic: 'shield', title: 'Audit entries (7 days)', value: week.length, sub: au.length + ' in total', href: '#/admin/audit' })}${tile({ cls: 'tea', ic: 'check', title: 'Integrity checks', value: bad ? bad + ' failing' : 'All passed', sub: checks.length + ' checks run' })}${tile({ ic: 'lock', title: 'Closed periods', value: DB.q('periods').filter(p => p.status === 'closed').length, sub: DB.q('periods').filter(p => (p.reopened || []).length).length + ' reopened', href: '#/accounting/periods' })}${tile({ ic: 'download', title: 'Exports logged', value: au.filter(a => a.action === 'export').length })}</div><div class="grid g2" style="margin-top:16px">${card('Latest logged activity', `<div class="tl">${au.slice(-8).reverse().map(a => `<div class="it"><b style="font-weight:500">${esc(a.name)}</b> ${esc(a.action)} ${esc(a.entity)}<br><span class="small muted">${esc(a.detail)} · ${ago(a.ts)}</span></div>`).join('')}</div>`, { ic: 'shield', acts: '<a class="btn sm" href="#/admin/audit">Open log</a>' })}${card('Controls at a glance', kv([['Two-officer payment rule', money(DB.setting('secondApprovalAmount')) + ' and above'], ['Manual journals approved by', 'A different finance officer'], ['Payments confirmed by', 'Someone other than the recorder'], ['Journals awaiting approval', DB.q('journals').filter(j => j.status === 'pending').length], ['Open exit exceptions', DB.q('exceptions').filter(x => x.status === 'Open').length], ['Unreconciled bank lines', DB.q('bankTxns').filter(t => !t.matched).length]]), { ic: 'scale' })}</div>`;
}
/* Finance Officer */
function dashFinOfficer() {
  const u = me(); const t = today(); const pend = Stat.pendingPay().filter(p => p.recordedBy !== u.id && !(p.confirmations || []).some(c => c.by === u.id)); const mine = DB.q('payments').filter(p => (p.confirmations || []).some(c => c.by === u.id) && p.confirmedAt && isoDate(p.confirmedAt) === t);
  const exp = DB.q('expenses').filter(e => e.status === 'approved'); const per = DB.q('periods').find(p => p.status === 'open');
  return `<div class="grid g4">${tile({ cls: 'dark', ic: 'coins', title: 'For me to confirm', value: pend.length, sub: moneyShort(sum(pend, p => p.amount)), href: '#/finance/confirm' })}${tile({ cls: 'tea', ic: 'check', title: 'Confirmed by me today', value: mine.length, sub: moneyShort(sum(mine, p => p.amount)) })}${tile({ ic: 'wallet', title: 'Expenses to disburse', value: exp.length, sub: moneyShort(sum(exp, e => e.amount)), href: '#/finance/expenses' })}${tile({ ic: 'scale', title: 'Bank lines to match', value: DB.q('bankTxns').filter(x => !x.matched).length, href: '#/accounting/bank' })}</div><div class="grid g2" style="margin-top:16px">${card('Today’s collections', `<div class="stat" style="margin-bottom:10px"><b>${money(sum(DB.q('payments').filter(p => p.status === 'confirmed' && p.date === t), p => p.amount))}</b><span>${DB.q('payments').filter(p => p.status === 'confirmed' && p.date === t).length} confirmed payments today</span></div>${hbars([['0–30', 0], ['31–60', 1], ['61–90', 2], ['90+', 3]].map(([l, i]) => ({ l: l + ' days overdue', v: Stat.aging()[i], warn: i > 1 })), moneyShort)}`, { ic: 'coins', acts: '<a class="btn sm" href="#/finance/collections">Collections</a>' })}${card('Month-end checklist', per ? `<p class="muted" style="margin-bottom:10px">${monthLabel(per.id)} is open.</p>${periodChecks(per.id).map(c => `<div class="row" style="padding:4px 0">${c.auto ? (c.ok ? icon('check', 'sm') : icon('warn', 'sm')) : icon('clock', 'sm')}<span class="grow">${esc(c.l)}</span><span class="small muted">${esc(c.d || (c.manual ? 'Manual' : ''))}</span></div>`).join('')}` : '<p class="muted">No open period.</p>', { ic: 'lock', acts: '<a class="btn sm" href="#/accounting/periods">Period close</a>' })}</div>`;
}
/* HR Officer */
function dashHrOfficer() {
  const t = today(); const att = Stat.attendanceToday(); const expiring = DB.q('vault').filter(v => v.expiry && v.expiry <= addDays(t, 30)); const lv = DB.q('leaves').filter(l => l.status === 'pending'); const onb = DB.q('tasks').filter(x => x.link?.type === 'employee' && x.status !== 'done');
  return `<div class="grid g4">${tile({ ic: 'users', title: 'Clocked in today', value: att.in, unit: '/ ' + att.total, caps: { v: att.in, max: att.total || 1 }, sub: att.late + ' late', href: '#/hr/attendance' })}${tile({ cls: 'tea', ic: 'calendar', title: 'Leave to approve', value: lv.length, href: '#/hr/leave' })}${tile({ ic: 'file', title: 'Documents expiring', value: expiring.length, sub: 'Within 30 days', href: '#/hr/vault' })}${tile({ cls: 'dark', ic: 'clipboard', title: 'Onboarding / exit tasks', value: onb.length, href: '#/hr/onboarding' })}</div><div class="grid g2" style="margin-top:16px">${card('Away today and next week', DB.q('leaves').filter(l => l.status === 'approved' && l.to >= t && l.from <= addDays(t, 7)).map(l => `<div class="row" style="padding:4px 0">${userChip(l.userId)}<span class="sp"></span><span class="small muted">${fmtDate(l.from)} – ${fmtDate(l.to)} · ${esc(l.type)}</span></div>`).join('') || '<p class="muted">Nobody is away.</p>', { ic: 'calendar' })}${card('Needs attention', `${kv([['Missed clock-outs this month', DB.q('attendance').filter(a => a.missed && monthKey(a.date) === monthKey(t)).length], ['Attendance corrections waiting', DB.q('approvals').filter(a => a.type === 'attcorr' && a.status === 'pending').length], ['Announcements awaiting acknowledgement', DB.q('announcements').filter(a => a.ack && DB.q('acks').filter(x => x.annId === a.id).length < DB.q('employees').filter(e => e.status === 'Active').length).length], ['Open exit exceptions', DB.q('exceptions').filter(x => x.status === 'Open').length], ['Appraisals pending', DB.q('appraisals').filter(a => a.status !== 'Calibrated').length]])}`, { ic: 'warn' })}</div>`;
}
/* Scheduled email reports (DSH-05) */
function dashSchedules() {
  return `<div class="alert info" style="margin-bottom:14px">${icon('mail', 'sm')}<span>Reports are emailed on a schedule, for example the daily collections summary to the MD and COO at 18:00. Schedules run once a day after their time.</span></div>${schedulesCard()}<div style="margin-top:16px">${table({ id: 'schedlog', title: 'Sent reports', rows: () => DB.q('outbox').filter(o => o.channel === 'email' && /Daily|summary|Sales to date|snapshot/i.test(o.text)).sort(by(o => o.ts, -1)), empty: 'Nothing has been sent yet. Use Send now on a schedule.', ps: 8, cols: [{ k: 'ts', l: 'Sent', r: o => fmtDT(o.ts), sv: o => o.ts }, { k: 'to', l: 'To' }, { k: 'text', l: 'Message' }] })}</div>`;
}

function dashExec() {
  const m = monthKey(today()); const ms = Stat.sales(m); const sv = sum(ms, s => s.total); const tgt = DB.q('targets').find(t => t.userId === 'team' && t.month === m); const col = Stat.collected(m), due = Math.max(Stat.due(m), 1);
  const range = +(UI.dashRange || 8); const keys = Stat.months(range); const dueA = keys.map(Stat.due), colA = keys.map(Stat.collected);
  const pc = Stat.plots(), age = Stat.aging(), att = Stat.attendanceToday(); const openT = DB.q('tickets').filter(t => !['Resolved', 'Closed'].includes(t.status));
  const links = [['Receivables', 'coins', moneyShort(Stat.receivables()) + ' outstanding · ' + moneyShort(sum(age)) + ' overdue', 'finance/collections'], ['Property inventory', 'estate', pc.available + ' plots available · ' + pc.reserved + ' reserved', 'inventory/estates'], ['Open tickets', 'headset', openT.length + ' open · ' + openT.filter(t => t.breached).length + ' breached SLA', 'cx/tickets'], ['Headcount', 'users', att.in + ' of ' + att.total + ' clocked in today · ' + att.late + ' late', 'hr/attendance']];
  return `<div class="grid gxm" style="align-items:start"><div class="stack">
    <div class="grid gx3">${tile({ ic: 'target', title: 'Sales this month', value: moneyShort(sv), unit: tgt ? '/ ' + moneyShort(tgt.value) : '', pc: tgt ? pct(sv, tgt.value) : null, caps: { v: sv, max: tgt ? tgt.value : sv || 1 }, sub: ms.length + ' sales closed', href: '#/crm/sales' })}
    ${tile({ cls: 'tea', ic: 'coins', title: 'Collected this month', value: moneyShort(col), unit: '/ ' + moneyShort(due) + ' due', pc: pct(col, due), caps: { v: col, max: due }, sub: 'Receipts issue in ' + Stat.medianReceiptMin() + ' min median after payment', href: '#/finance/payments' })}
    <div class="cta">${leafBg}<h3>Take collections <span class="lw">to the next level</span></h3><a class="btn" href="#/finance/collections">Open collections ${icon('chevr', 'sm')}</a></div></div>
    ${dashFilterCard()}
    ${card('Statistics', `<div class="row" style="margin-bottom:6px"><div class="legend"><span><i style="background:var(--ever)"></i>Due</span><span><i style="background:var(--lawn)"></i>Collected</span></div><span class="sp"></span><label class="chip"><select data-on="dash.range" aria-label="Range">${opts([[6, 'Last 6 months'], [8, 'Last 8 months'], [12, 'Last 12 months']], range)}</select></label></div>${pillBars({ labels: keys.map(k => monthLabel(k).split(' ')[0]), a: dueA, b: colA, fmt: moneyShort, cur: keys.length - 1, hl: keys.length - 1 })}`, { ic: 'trend' })}
    <div class="grid g3">${card('Inventory', hbars(PLOT_STATUSES.map(s => ({ l: PLOT_LABEL[s], v: pc[s] }))), { ic: 'estate', acts: '<a class="btn sm" href="#/inventory/estates">Open</a>' })}${card('Receivables aging', `<div class="stack" style="gap:10px">${['0–30 days', '31–60 days', '61–90 days', '90+ days'].map((l, i) => `<div><div class="row small"><span>${l}</span><span class="sp"></span><b>${moneyShort(age[i])}</b></div>${progress(age[i], Math.max(...age, 1), i > 1)}</div>`).join('')}</div>`, { ic: 'scale', acts: '<a class="btn sm" href="#/finance/collections">Open</a>' })}${card('Sales funnel', hbars(['New', 'Contacted', 'Inspection', 'Negotiation', 'Reserved', 'Won'].map(s => ({ l: s, v: DB.q('leads').filter(l => l.stage === s).length }))), { ic: 'target', acts: '<a class="btn sm" href="#/crm/pipeline">Open</a>' })}</div></div>
  <div class="stack"><div class="qlinks"><a class="ql" href="#/chat"><span class="ci">${icon('chat')}</span><b>Team chat</b><span class="d">${chatUnread()} unread</span></a><a class="ql" href="#/learning"><span class="ci">${icon('cap')}</span><b>Learning</b><span class="d">Maximizing Chronos</span></a></div>
  ${links.map(([t, ic, d, h]) => `<a class="ql" href="#/${h}"><span class="ci">${icon(ic)}</span><span class="ar">${icon('arrowur', 'sm')}</span><b>${t}</b><span class="d">${d}</span></a>`).join('')}
  <a class="ql" href="#/approvals"><span class="ci">${icon('shield')}</span><span class="ar">${icon('arrowur', 'sm')}</span><b>Pending approvals</b><span class="d">${approvalCount()} waiting for you · ${DB.q('approvals').filter(a => a.status === 'pending').length} in total</span></a></div></div>`;
}
