function scorecardMini(team, m) {
  const rows = team.map(u => { const ks = typeof kpisFor === 'function' ? kpisFor(u) : []; const res = ks.map(k => kpiStatus(k, kpiActual(k, u.id, m))); const g = res.filter(r => r.s === 'g').length, a = res.filter(r => r.s === 'a').length, r = res.filter(x => x.s === 'r').length; return `<tr><td>${userChip(u.id)}</td><td>${g ? `<span class="sig g"></span> ${g}` : ''} ${a ? `<span class="sig a"></span> ${a}` : ''} ${r ? `<span class="sig r"></span> ${r}` : ''}</td><td class="muted">${ks.length} KPIs</td></tr>`; }).join('');
  return rows ? `<table class="tbl"><thead><tr><th>Person</th><th>Traffic lights</th><th></th></tr></thead><tbody>${rows}</tbody></table>` : emptyState('No team members');
}

/* personal dashboard */
function myAttendanceToday() { return DB.q('attendance').find(a => a.userId === SESS.uid && a.date === today()); }
function clockCard() {
  const a = myAttendanceToday(); const lt = DB.setting('lateTime');
  let body;
  if (!a) body = `<p class="muted" style="margin-bottom:12px">Resumption is ${lt}. Tap to clock in on web or phone.</p><button class="btn primary" data-act="clock.in">${icon('clock', 'sm')} Clock in</button>`;
  else if (!a.out) body = `<div class="stat" style="margin-bottom:12px"><b>${fmtTime(a.in)}</b><span>Clocked in · ${esc(a.mode)} ${a.late ? '· late' : ''}</span></div><button class="btn dark" data-act="clock.out">${icon('clock', 'sm')} Clock out</button>`;
  else body = `<div class="stat"><b>${fmtTime(a.in)} – ${fmtTime(a.out)}</b><span>${Math.round((a.out - a.in) / 36e5 * 10) / 10} hours · ${esc(a.mode)}</span></div>`;
  return `<section class="card ${a && !a.out ? '' : ''}"><div class="ch"><span class="ci" style="width:36px;height:36px;border-radius:12px;background:#fff;display:grid;place-items:center">${icon('clock')}</span><h3>Attendance</h3><span class="sp"></span>${a ? spill(a.out ? 'Done' : a.late ? 'Late' : 'On time', a.late ? 'warn' : 'ok') : spill('Not clocked in', 'mute')}</div>${body}</section>`;
}
ACT['clock.in'] = () => openForm({ title: 'Clock in', submit: 'Clock in', fields: [{ n: 'mode', l: 'Work mode', t: 'select', req: true, blank: false, o: ['Office', 'Remote', 'Field'], v: 'Office' }, { n: 'ok', l: 'I am at the office or on the office network', t: 'check', show: v => (v.mode || 'Office') === 'Office', hint: 'Office clock-ins are confirmed by location or the office network.' }, { n: 'where', l: 'Where are you working from?', show: v => v.mode && v.mode !== 'Office', ph: 'e.g. Home, Velcrest site' }], vals: { mode: 'Office' }, onSubmit: v => { if (v.mode === 'Office' && !v.ok) { toast('Confirm you are at the office, or choose Remote or Field.', 'warn'); return false; } const t = new Date(); const late = t.getHours() * 60 + t.getMinutes() > (+DB.setting('lateTime').split(':')[0]) * 60 + +DB.setting('lateTime').split(':')[1]; DB.add('attendance', { userId: SESS.uid, date: today(), in: Date.now(), out: null, mode: v.mode, where: v.where || '', late, missed: false, verified: v.mode === 'Office' ? 'office-network' : 'declared' }); toast('Clocked in at ' + fmtTime(Date.now())); render(); } });
ACT['clock.out'] = () => { const a = myAttendanceToday(); DB.set('attendance', a.id, { out: Date.now() }, { action: 'clock-out' }); toast('Clocked out. Have a good evening.'); render(); };

