  const e = empOf(u.id); const m = monthKey(t); const ks = kpisFor(u); const nextSess = DB.q('sessions').filter(s => s.date >= t && (s.invitees || []).includes(u.id)).sort(by(s => s.date))[0];
  const appr = DB.q('approvals').filter(canDecide); const myTg = DB.q('targets').find(x => x.userId === u.id && x.month === m); const mySales = Stat.sales(m).filter(s => s.officer === u.id);
